// Read button taps and edit replies from YOUR chat only. Others are ignored.
const CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
const res = $input.first().json;
if (res.error || res.ok === false) throw new Error('Telegram getUpdates failed: ' + JSON.stringify(res.error || res.description || '').slice(0, 300) +
  ' (409 = another webhook/trigger uses this bot)');
const ups = res.result || [];
if (!ups.length) return [];
const actions = [];
for (const u of ups) {
  const cq = u.callback_query;
  if (cq && String(cq.from?.id) === CHAT_ID) {
    const m = String(cq.data || '').match(/^(send|edit|fsend|fedit):(L-\d{4,})$/);
    if (m) actions.push({ type: m[1], lead: m[2], cq_id: cq.id, message_id: cq.message?.message_id });
    else actions.push({ type: 'ignore', cq_id: cq.id });
    continue;
  }
  const msg = u.message;
  if (msg && String(msg.chat?.id) === CHAT_ID && msg.reply_to_message) {
    const replyText = String(msg.reply_to_message.text || '');
    const mf = replyText.match(/EDIT FOLLOW-UP (L-\d{4,})/);
    const mr = replyText.match(/EDIT (L-\d{4,})/);
    if (mf && String(msg.text || '').trim().length > 20) {
      actions.push({ type: 'fedit_text', lead: mf[1], text: String(msg.text).trim().slice(0, 4000) });
    } else if (mr && String(msg.text || '').trim().length > 20) {
      actions.push({ type: 'edit_text', lead: mr[1], text: String(msg.text).trim().slice(0, 4000) });
    }
  }
}
if (!actions.length) return [];
return [{ json: { actions, ackOffset: Math.max(...ups.map(u => u.update_id)) + 1 } }];

const CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
const keyboard = (leadId) => ({ inline_keyboard: [[
  { text: '✅ Send', callback_data: 'send:' + leadId }, { text: '✏️ Edit', callback_data: 'edit:' + leadId } ]] });
const fkeyboard = (leadId) => ({ inline_keyboard: [[
  { text: '✅ Send', callback_data: 'fsend:' + leadId }, { text: '✏️ Edit', callback_data: 'fedit:' + leadId } ]] });
const preview = (r, extra) => [
  `✉️ AI reply draft ${r.Lead_ID} (${String(r.Score || '').toUpperCase()}) — Odoo #${r.Odoo_Lead_ID}`,
  `To: ${r.Name} <${r.Email}>`, extra || '', `Subject: ${r.Reply_Subject}`, '———', String(r.Reply_Draft).slice(0, 3000), '———',
  'Tap ✅ Send (goes to the demo inbox) or ✏️ Edit.'].filter(Boolean).join('\n');
const fpreview = (r, extra) => [
  `🔁 3-day follow-up draft ${r.Lead_ID} (${String(r.Score || '').toUpperCase()}) — Odoo #${r.Odoo_Lead_ID}`,
  `To: ${r.Name} <${r.Email}>`, extra || '', `Subject: Re: ${r.Reply_Subject || 'Your SunGuard Solar & CCTV inquiry'}`, '———', String(r.Followup_Draft).slice(0, 3000), '———',
  'Tap ✅ Send (goes to the demo inbox) or ✏️ Edit.'].filter(Boolean).join('\n');

const DEMO_INBOX = 'YOUR_DEMO_INBOX';
const tidy = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [String(k).trim(), v]));
const rows = Object.fromEntries($input.all().map(i => tidy(i.json)).filter(r => r.Lead_ID).map(r => [String(r.Lead_ID).trim(), r]));
const { actions } = $('Parse Telegram updates').first().json;
const now = new Date().toISOString();
const ans = (id, text) => id ? [{ tg_method: 'answerCallbackQuery', tg_body: { callback_query_id: id, text } }] : [];
const out = [];

for (const a of actions) {
  const r = rows[a.lead];
  if (a.type === 'ignore' || !r) {
    out.push({ json: { route: 'other', sheet: null, sheet_followup: null, tg: ans(a.cq_id, r ? 'Unknown button' : 'Lead not found') } });
    continue;
  }

  // Initial reply actions (send / edit / edit_text)
  if (['send', 'edit', 'edit_text'].includes(a.type)) {
    const keep = { Lead_ID: r.Lead_ID, Reply_Status: r.Reply_Status || '', Reply_Subject: r.Reply_Subject || '',
                   Reply_Draft: r.Reply_Draft || '', Reply_Sent_At: r.Reply_Sent_At || '' };
    const status = String(r.Reply_Status || '').trim();
    if (status === 'Sent') { out.push({ json: { route: 'other', sheet: null, sheet_followup: null, tg: ans(a.cq_id, 'Already sent ✅') } }); continue; }
    if (a.type === 'send') {
      if (status !== 'Awaiting approval') { out.push({ json: { route: 'other', sheet: null, sheet_followup: null, tg: ans(a.cq_id, 'No draft to send') } }); continue; }
      out.push({ json: { route: 'send',
        email: { to: DEMO_INBOX, subject: `[DEMO → ${r.Email}] ${r.Reply_Subject}`,
                 text: `${r.Reply_Draft}\n\n---\nDemo mode: in production this email goes to ${r.Name} <${r.Email}>. Lead ${r.Lead_ID}, Odoo #${r.Odoo_Lead_ID}.` },
        rpc: { model: 'crm.lead', method: 'message_post', args: [[Number(r.Odoo_Lead_ID)]], kwargs: {
          body: `AI reply approved in Telegram and sent (demo inbox) for ${r.Lead_ID}. Subject: ${r.Reply_Subject}`,
          message_type: 'comment', subtype_xmlid: 'mail.mt_note' } },
        sheet: { ...keep, Reply_Status: 'Sent', Reply_Sent_At: now },
        sheet_followup: null,
        tg: [...ans(a.cq_id, 'Sent ✅'),
          ...(a.message_id ? [{ tg_method: 'editMessageReplyMarkup', tg_body: { chat_id: CHAT_ID, message_id: a.message_id, reply_markup: { inline_keyboard: [] } } }] : []),
          { tg_method: 'sendMessage', tg_body: { chat_id: CHAT_ID, text: `✅ ${r.Lead_ID} sent to the demo inbox (for ${r.Name}). Note added to Odoo #${r.Odoo_Lead_ID}.` } }] } });
    } else if (a.type === 'edit') {
      out.push({ json: { route: 'other', sheet: null, sheet_followup: null, tg: [...ans(a.cq_id, 'Send the new text'),
        { tg_method: 'sendMessage', tg_body: { chat_id: CHAT_ID, text: `✏️ EDIT ${r.Lead_ID}\nReply to this message with the full new email text.`,
          reply_markup: { force_reply: true, input_field_placeholder: 'New email text' } } }] } });
    } else if (a.type === 'edit_text') {
      const nr = { ...r, Reply_Draft: a.text };
      out.push({ json: { route: 'other', sheet: { ...keep, Reply_Status: 'Awaiting approval', Reply_Draft: a.text }, sheet_followup: null,
        tg: [{ tg_method: 'sendMessage', tg_body: { chat_id: CHAT_ID, text: preview(nr, '(edited by you)'), reply_markup: keyboard(r.Lead_ID) } }] } });
    }
    continue;
  }

  // 3-day follow-up actions (fsend / fedit / fedit_text)
  const fkeep = { Lead_ID: r.Lead_ID, Followup_Status: r.Followup_Status || '', Followup_Draft: r.Followup_Draft || '', Followup_Sent_At: r.Followup_Sent_At || '' };
  const fstatus = String(r.Followup_Status || '').trim();
  if (fstatus === 'Sent') { out.push({ json: { route: 'other', sheet: null, sheet_followup: null, tg: ans(a.cq_id, 'Follow-up already sent ✅') } }); continue; }
  if (a.type === 'fsend') {
    if (fstatus !== 'Awaiting approval') { out.push({ json: { route: 'other', sheet: null, sheet_followup: null, tg: ans(a.cq_id, 'No follow-up draft to send') } }); continue; }
    const subj = r.Reply_Subject ? `Re: ${r.Reply_Subject}` : 'Follow-up: SunGuard Solar & CCTV';
    out.push({ json: { route: 'send',
      email: { to: DEMO_INBOX, subject: `[DEMO → ${r.Email}] ${subj}`,
               text: `${r.Followup_Draft}\n\n---\nDemo mode: in production this follow-up goes to ${r.Name} <${r.Email}>. Lead ${r.Lead_ID}, Odoo #${r.Odoo_Lead_ID}.` },
      rpc: { model: 'crm.lead', method: 'message_post', args: [[Number(r.Odoo_Lead_ID)]], kwargs: {
        body: `3-day follow-up approved in Telegram and sent (demo inbox) for ${r.Lead_ID}. Subject: ${subj}`,
        message_type: 'comment', subtype_xmlid: 'mail.mt_note' } },
      sheet: null,
      sheet_followup: { ...fkeep, Followup_Status: 'Sent', Followup_Sent_At: now },
      tg: [...ans(a.cq_id, 'Follow-up sent ✅'),
        ...(a.message_id ? [{ tg_method: 'editMessageReplyMarkup', tg_body: { chat_id: CHAT_ID, message_id: a.message_id, reply_markup: { inline_keyboard: [] } } }] : []),
        { tg_method: 'sendMessage', tg_body: { chat_id: CHAT_ID, text: `✅ Follow-up ${r.Lead_ID} sent to the demo inbox (for ${r.Name}). Note added to Odoo #${r.Odoo_Lead_ID}.` } }] } });
  } else if (a.type === 'fedit') {
    out.push({ json: { route: 'other', sheet: null, sheet_followup: null, tg: [...ans(a.cq_id, 'Send the new follow-up text'),
      { tg_method: 'sendMessage', tg_body: { chat_id: CHAT_ID, text: `✏️ EDIT FOLLOW-UP ${r.Lead_ID}\nReply to this message with the full new follow-up text.`,
        reply_markup: { force_reply: true, input_field_placeholder: 'New follow-up text' } } }] } });
  } else if (a.type === 'fedit_text') {
    const nr = { ...r, Followup_Draft: a.text };
    out.push({ json: { route: 'other', sheet: null, sheet_followup: { ...fkeep, Followup_Status: 'Awaiting approval', Followup_Draft: a.text },
      tg: [{ tg_method: 'sendMessage', tg_body: { chat_id: CHAT_ID, text: fpreview(nr, '(edited by you)'), reply_markup: fkeyboard(r.Lead_ID) } }] } });
  }
}
return out;

const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) throw new Error('Odoo config not found. Check ODOO_* env vars and sunguard_crm.ids.');
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };

const plan = $('Is it a Send?').all(0);
return $input.all().map((it, i) => ({ json: { rpc: { ...plan[i].json.rpc, kwargs: { ...plan[i].json.rpc.kwargs, context } } } }));

// Back to the plan items of the send branch (same order as the Gmail and Odoo calls).
const plan = $('Is it a Send?').all(0);
return $input.all().map((it, i) => {
  if (it.json.error) throw new Error('Odoo note failed: ' + JSON.stringify(it.json.error).slice(0, 200));
  return { json: plan[i].json };
});
